/**
 * @fileoverview Verification-only AST linter enforcing 100% substantive TSDoc coverage
 * across all Angular TypeScript source files in `pulse-query-ng-web/src`.
 *
 * Rejects missing JSDoc comments as well as placeholder stubs (`@docs`, `doc`,
 * `Autogenerated doc`).
 */

import { JSDocableNode, Node, ParameterDeclaration, Project } from "ts-morph";
import * as path from "path";

const BANNED_PATTERNS: readonly RegExp[] = [
  /\bAutogenerated doc\b/i,
  /^@docs$/i,
  /^doc$/i,
  /\/\*\*\s*@docs\s*\*\//i,
  /\/\*\*\s*doc\s*\*\//i,
];

/**
 * Checks whether a raw JSDoc comment or description contains banned placeholder text.
 *
 * @param text - The JSDoc comment text to inspect.
 * @returns True if the text is empty or matches a banned placeholder pattern.
 */
export function isPlaceholderDoc(text: string): boolean {
  const trimmed = text.trim();
  if (!trimmed) {
    return true;
  }
  return BANNED_PATTERNS.some((pattern) => pattern.test(trimmed));
}

/**
 * Validates that a JSDocable AST node has at least one non-placeholder JSDoc block.
 *
 * @param node - AST node supporting JSDoc annotations.
 * @param label - Human-readable identifier for diagnostic reporting.
 * @param filePath - Relative file path containing the node.
 * @param errors - Mutable array accumulating validation errors.
 */
function verifyNodeDoc(
  node: JSDocableNode & Node,
  label: string,
  filePath: string,
  errors: string[],
): void {
  const docs = node.getJsDocs();
  if (docs.length === 0) {
    errors.push(
      `${filePath}:${node.getStartLineNumber()} - Missing TSDoc on ${label}`,
    );
    return;
  }

  for (const doc of docs) {
    const comment = doc.getDescription().trim();
    const fullText = doc.getText().trim();
    if (isPlaceholderDoc(comment) && !doc.getTags().length) {
      errors.push(
        `${filePath}:${node.getStartLineNumber()} - Empty TSDoc description on ${label}`,
      );
    } else if (
      BANNED_PATTERNS.some((p) => p.test(comment) || p.test(fullText))
    ) {
      errors.push(
        `${filePath}:${node.getStartLineNumber()} - Placeholder TSDoc forbidden on ${label}`,
      );
    }
  }
}

/**
 * Validates that every parameter on a function, method, or constructor is documented with `@param`.
 *
 * @param node - Callable AST node with JSDoc annotations.
 * @param params - Parameter declarations belonging to the callable.
 * @param label - Human-readable callable label.
 * @param filePath - Relative file path containing the callable.
 * @param errors - Mutable array accumulating validation errors.
 */
function verifyParameterDocs(
  node: JSDocableNode & Node,
  params: readonly ParameterDeclaration[],
  label: string,
  filePath: string,
  errors: string[],
): void {
  if (params.length === 0) {
    return;
  }
  const docs = node.getJsDocs();
  if (docs.length === 0) {
    return;
  }
  const paramTags = new Map<string, string>();
  for (const doc of docs) {
    for (const tag of doc.getTags()) {
      if (tag.getTagName() === "param") {
        const tagText = tag.getText();
        const commentText = tag.getCommentText()?.trim() ?? "";
        for (const p of params) {
          const pName = p.getName();
          if (tagText.includes(pName)) {
            paramTags.set(pName, commentText);
          }
        }
      }
    }
  }

  for (const param of params) {
    const pName = param.getName();
    if (!paramTags.has(pName)) {
      errors.push(
        `${filePath}:${param.getStartLineNumber()} - Missing @param ${pName} TSDoc on ${label}`,
      );
    } else if (isPlaceholderDoc(paramTags.get(pName) ?? "")) {
      errors.push(
        `${filePath}:${param.getStartLineNumber()} - Placeholder or empty @param ${pName} description on ${label}`,
      );
    }
  }
}

/**
 * Runs the AST documentation verifier across the Angular frontend project.
 *
 * @returns Process exit code (`0` when all files pass, `1` when violations exist).
 */
export function verifyFrontendDocs(): number {
  const rootDir = path.resolve(__dirname, "..");
  const tsConfigFilePath = path.join(
    rootDir,
    "pulse-query-ng-web",
    "tsconfig.app.json",
  );
  const project = new Project({ tsConfigFilePath });

  const sourceFiles = project
    .getSourceFiles()
    .filter(
      (f) =>
        f.getFilePath().includes("pulse-query-ng-web/src/") &&
        !f.getFilePath().includes(".spec.ts") &&
        !f.getFilePath().includes("api-client"),
    );

  const errors: string[] = [];

  for (const sf of sourceFiles) {
    const relPath = path.relative(rootDir, sf.getFilePath());
    const fullText = sf.getFullText();

    if (!fullText.includes("@fileoverview")) {
      errors.push(`${relPath}:1 - Missing @fileoverview header comment`);
    }
    if (
      /\/\*\*\s*(@docs|doc)\s*\*\//i.test(fullText) ||
      /\bAutogenerated doc\b/i.test(fullText)
    ) {
      errors.push(
        `${relPath}:1 - File contains banned placeholder doc comment (@docs / doc)`,
      );
    }

    for (const cls of sf.getClasses()) {
      const clsName = cls.getName() ?? "<anonymous class>";
      verifyNodeDoc(cls, `class ${clsName}`, relPath, errors);
      for (const prop of cls.getProperties()) {
        verifyNodeDoc(
          prop,
          `property ${clsName}.${prop.getName()}`,
          relPath,
          errors,
        );
      }
      for (const ctor of cls.getConstructors()) {
        verifyNodeDoc(ctor, `constructor ${clsName}`, relPath, errors);
        verifyParameterDocs(
          ctor,
          ctor.getParameters(),
          `constructor ${clsName}`,
          relPath,
          errors,
        );
      }
      for (const method of cls.getMethods()) {
        const mLabel = `method ${clsName}.${method.getName()}`;
        verifyNodeDoc(method, mLabel, relPath, errors);
        verifyParameterDocs(
          method,
          method.getParameters(),
          mLabel,
          relPath,
          errors,
        );
      }
      for (const getter of cls.getGetAccessors()) {
        verifyNodeDoc(
          getter,
          `getter ${clsName}.${getter.getName()}`,
          relPath,
          errors,
        );
      }
      for (const setter of cls.getSetAccessors()) {
        verifyNodeDoc(
          setter,
          `setter ${clsName}.${setter.getName()}`,
          relPath,
          errors,
        );
      }
    }

    for (const intf of sf.getInterfaces()) {
      const intfName = intf.getName();
      verifyNodeDoc(intf, `interface ${intfName}`, relPath, errors);
      for (const prop of intf.getProperties()) {
        verifyNodeDoc(
          prop,
          `interface property ${intfName}.${prop.getName()}`,
          relPath,
          errors,
        );
      }
      for (const method of intf.getMethods()) {
        verifyNodeDoc(
          method,
          `interface method ${intfName}.${method.getName()}`,
          relPath,
          errors,
        );
      }
    }

    for (const typeAlias of sf.getTypeAliases()) {
      verifyNodeDoc(typeAlias, `type ${typeAlias.getName()}`, relPath, errors);
    }

    for (const fn of sf.getFunctions()) {
      const fnName = fn.getName() ?? "<anonymous function>";
      verifyNodeDoc(fn, `function ${fnName}`, relPath, errors);
      verifyParameterDocs(
        fn,
        fn.getParameters(),
        `function ${fnName}`,
        relPath,
        errors,
      );
    }

    for (const enumDec of sf.getEnums()) {
      const enumName = enumDec.getName();
      verifyNodeDoc(enumDec, `enum ${enumName}`, relPath, errors);
      for (const member of enumDec.getMembers()) {
        verifyNodeDoc(
          member,
          `enum member ${enumName}.${member.getName()}`,
          relPath,
          errors,
        );
      }
    }
  }

  if (errors.length > 0) {
    console.error(`TSDoc verification failed with ${errors.length} error(s):`);
    for (const err of errors) {
      console.error(`  - ${err}`);
    }
    return 1;
  }

  console.log(
    `Verified ${sourceFiles.length} TypeScript source files with 100% TSDoc coverage.`,
  );
  return 0;
}

if (require.main === module) {
  process.exit(verifyFrontendDocs());
}
